"""Write the experiment task sets to evals/. Run: python -m experiments.build"""

from __future__ import annotations

from pathlib import Path

import yaml

from experiments.scenarios import taskset_a, taskset_b

ROOT = Path(__file__).resolve().parents[1]
TARGETS = {"exp_a_planner": taskset_a, "exp_b_memory": taskset_b}
HEADER = (
    "# Generated by `python -m experiments.build` from experiments/scenarios.py. Do not edit.\n"
)


def main() -> None:
    for directory, make in TARGETS.items():
        out = ROOT / "evals" / directory
        out.mkdir(parents=True, exist_ok=True)
        body = yaml.safe_dump(make(), allow_unicode=True, sort_keys=False, width=100)
        (out / "taskset.yaml").write_text(HEADER + body, encoding="utf-8")
        print(f"wrote {out / 'taskset.yaml'}")


if __name__ == "__main__":
    main()
